import{_ as t,o as a,c as o,ag as i}from"./chunks/framework.DqVSm8kp.js";const p=JSON.parse('{"title":"Discovered with LLMxRay","description":"","frontmatter":{},"headers":[],"relativePath":"en/community/showcase.md","filePath":"en/community/showcase.md"}'),r={name:"en/community/showcase.md"};function n(s,e,c,h,l,u){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="discovered-with-llmxray" tabindex="-1">Discovered with LLMxRay <a class="header-anchor" href="#discovered-with-llmxray" aria-label="Permalink to &quot;Discovered with LLMxRay&quot;">​</a></h1><p>A curated collection of interesting findings, surprising behaviors, and valuable insights discovered by the community using LLMxRay.</p><h2 id="how-to-submit" tabindex="-1">How to Submit <a class="header-anchor" href="#how-to-submit" aria-label="Permalink to &quot;How to Submit&quot;">​</a></h2><p>Found something interesting? We&#39;d love to feature it.</p><ol><li>Open a <a href="https://github.com/LogneBudo/llmxray/issues/new?template=showcase-submission.yml" target="_blank" rel="noreferrer">Showcase Submission</a> issue</li><li>Fill in the structured form: what you found, which models, how to reproduce</li><li>Include screenshots from LLMxRay if possible</li><li>We&#39;ll review and add it to this page</li></ol><hr><h2 id="featured-discoveries" tabindex="-1">Featured Discoveries <a class="header-anchor" href="#featured-discoveries" aria-label="Permalink to &quot;Featured Discoveries&quot;">​</a></h2><h3 id="temperature-cliff-on-code-generation" tabindex="-1">Temperature cliff on code generation <a class="header-anchor" href="#temperature-cliff-on-code-generation" aria-label="Permalink to &quot;Temperature cliff on code generation&quot;">​</a></h3><p><strong>Contributor:</strong> LogneBudo | <strong>Models:</strong> Mistral 7B | <strong>Date:</strong> March 2026</p><p>Using the Compare feature with a Temperature Sweep preset, we found that Mistral 7B produces significantly more accurate Python code at temperature 0.2 than at 0.7. At 0.7, the model introduces creative but incorrect variable names and occasionally hallucinates API methods. The token confidence coloring in Chat Diagnostics made the uncertainty visible — tokens in the 0.7 output showed consistently lower confidence (more orange) around function calls.</p><h3 id="deepseek-r1-thinking-depth-varies-by-question-type" tabindex="-1">DeepSeek-R1 thinking depth varies by question type <a class="header-anchor" href="#deepseek-r1-thinking-depth-varies-by-question-type" aria-label="Permalink to &quot;DeepSeek-R1 thinking depth varies by question type&quot;">​</a></h3><p><strong>Contributor:</strong> LogneBudo | <strong>Models:</strong> DeepSeek-R1 7B | <strong>Date:</strong> March 2026</p><p>The Reasoning tab revealed that DeepSeek-R1&#39;s <code>&lt;think&gt;</code> blocks are dramatically longer for math word problems (GSM8K) than for factual recall (TruthfulQA). On GSM8K, the model averages 12-15 reasoning steps with explicit arithmetic verification. On TruthfulQA, it typically uses 2-3 steps before committing to an answer. This was visible in the Benchmark results — GSM8K had higher TTFT but also higher accuracy when the thinking budget was uncapped.</p><h3 id="quantization-impact-on-benchmark-accuracy" tabindex="-1">Quantization impact on benchmark accuracy <a class="header-anchor" href="#quantization-impact-on-benchmark-accuracy" aria-label="Permalink to &quot;Quantization impact on benchmark accuracy&quot;">​</a></h3><p><strong>Contributor:</strong> LogneBudo | <strong>Models:</strong> Llama 3.2 3B (Q4_0 vs Q8_0) | <strong>Date:</strong> March 2026</p><p>Running the same ARC-Challenge suite on Llama 3.2 at Q4_0 and Q8_0 quantization using the Benchmark page showed a 4.2% accuracy drop at Q4_0. The per-category breakdown revealed that the drop was concentrated in physics questions (7.1% drop) while biology questions were barely affected (0.8% drop). The logprob distributions confirmed that Q4_0 was less confident overall, but the confidence gap widened specifically on questions requiring multi-step numerical reasoning.</p><hr><p><em>Want to see your finding here? <a href="https://github.com/LogneBudo/llmxray/issues/new?template=showcase-submission.yml" target="_blank" rel="noreferrer">Submit a showcase issue</a>.</em></p>',18)])])}const m=t(r,[["render",n]]);export{p as __pageData,m as default};
